export const AIRPORTS = {
  JFK: {code:'JFK', name:'John F. Kennedy', city:'New York', lat:40.6413, lon:-73.7781},
  ATL: {code:'ATL', name:'Hartsfield–Jackson', city:'Atlanta', lat:33.6407, lon:-84.4277},
  ORD: {code:'ORD', name:'O’Hare', city:'Chicago', lat:41.9742, lon:-87.9073},
  LAX: {code:'LAX', name:'Los Angeles International', city:'Los Angeles', lat:33.9416, lon:-118.4085},
  DFW: {code:'DFW', name:'Dallas Fort Worth', city:'Dallas–Fort Worth', lat:32.8998, lon:-97.0403},
  LHR: {code:'LHR', name:'Heathrow', city:'London', lat:51.47, lon:-0.4543}
};
export const RADII=[25,50,100,150];
export const STALE_SECONDS=120;
const numeric=x=>typeof x==='number'&&Number.isFinite(x);
const text=(v,n=40)=>typeof v==='string'?v.trim().slice(0,n):'';
export function distanceNm(lat,lon,a){const r=Math.PI/180,dlat=(lat-a.lat)*r,dlon=(lon-a.lon)*r;const h=Math.sin(dlat/2)**2+Math.cos(a.lat*r)*Math.cos(lat*r)*Math.sin(dlon/2)**2;return 3440.065*2*Math.atan2(Math.sqrt(h),Math.sqrt(Math.max(0,1-h)));}
export function normalizeFlights(payload,airport,radius,at=Date.now()){
  if(!payload||!Array.isArray(payload.ac)||!numeric(payload.now))throw new Error('The flight provider returned an unexpected response.');
  const feedTime=payload.now>1e12?payload.now/1000:payload.now;
  if(at/1000-feedTime>STALE_SECONDS||feedTime-at/1000>30)throw new Error('The flight provider’s observation time is stale or invalid.');
  const seen=new Set(),rows=[];let excluded=0;
  for(const a of payload.ac){
    if(!a||typeof a.hex!=='string'||!/^~?[0-9a-f]{6}$/i.test(a.hex)||seen.has(a.hex.toLowerCase())||!numeric(a.lat)||!numeric(a.lon)||Math.abs(a.lat)>90||Math.abs(a.lon)>180||!numeric(a.seen_pos)||a.seen_pos<0||a.seen_pos>STALE_SECONDS){excluded++;continue;}
    const positionTime=feedTime-a.seen_pos;
    if(at/1000-positionTime>STALE_SECONDS){excluded++;continue;}
    const distance=distanceNm(a.lat,a.lon,AIRPORTS[airport]);
    if(distance>radius+1){excluded++;continue;}
    seen.add(a.hex.toLowerCase());
    rows.push({id:a.hex.toLowerCase(),callsign:text(a.flight),registration:text(a.r),aircraftType:text(a.t,12),lat:a.lat,lon:a.lon,altitudeFt:numeric(a.alt_baro)?a.alt_baro:null,onGround:a.alt_baro==='ground'?true:numeric(a.alt_baro)?false:null,groundspeedKt:numeric(a.gs)&&a.gs>=0?a.gs:null,heading:numeric(a.track)?((a.track%360)+360)%360:null,positionTime,distanceNm:Math.round(distance*10)/10});
  }
  rows.sort((a,b)=>a.distanceNm-b.distanceNm);
  return {provider:'ADSB.lol',providerUrl:'https://www.adsb.lol/',license:'ODbL-1.0',airport,radiusNm:radius,feedTime,fetchedAt:at/1000,rows,excluded,refreshSeconds:15,scope:'Reported aircraft within the selected radius. Coverage is incomplete; nearby aircraft are not necessarily arriving at or departing this airport.'};
}

const cache=new Map(),pending=new Map();
let providerRetryAt=0,nextProviderAt=0;
const json=(body,status=200,headers={})=>new Response(JSON.stringify(body),{status,headers:{'content-type':'application/json; charset=utf-8','cache-control':'no-store','x-content-type-options':'nosniff',...headers}});
export function parseQuery(url){const airport=url.searchParams.get('airport')||'JFK';const raw=url.searchParams.get('radius')||'100';const radius=Number(raw);if(!Object.hasOwn(AIRPORTS,airport)||!RADII.includes(radius)||!/^\d+$/.test(raw))return null;return{airport,radius};}
async function readBounded(response){if(Number(response.headers.get('content-length'))>4000000)throw new Error('The flight provider response is too large.');const reader=response.body?.getReader();if(!reader)throw new Error('The flight provider returned no data.');const chunks=[];let bytes=0;try{while(true){const {done,value}=await reader.read();if(done)break;bytes+=value.byteLength;if(bytes>4000000){await reader.cancel();throw new Error('The flight provider response is too large.');}chunks.push(value);}}finally{reader.releaseLock();}const buffer=new Uint8Array(bytes);let offset=0;for(const c of chunks){buffer.set(c,offset);offset+=c.length;}return JSON.parse(new TextDecoder().decode(buffer));}
export async function flightAPI(request,env={},ctx={},upstream=fetch){
 const query=parseQuery(new URL(request.url));if(!query)return json({error:'Choose one of the six airports and a 25, 50, 100, or 150 NM radius.'},400);
 const {airport,radius}=query,key=`${airport}:${radius}`;const prior=cache.get(key);if(prior&&Date.now()<prior.expires)return json(prior.body,prior.status,prior.headers);
 if(pending.has(key))return json(...await pending.get(key));
 const job=(async()=>{const cfCache=globalThis.caches?.default;const cacheKey=new Request(`${new URL(request.url).origin}/_flight-cache/v1/${airport}/${radius}`);
 try{
  const saved=await cfCache?.match(cacheKey);if(saved){const body=await saved.json();cache.set(key,{body,status:200,headers:{},expires:Date.now()+10000});return[body,200,{}];}
  if(Date.now()<providerRetryAt){const error=new Error('The flight provider is rate-limiting requests. Please wait before refreshing.');error.retrySeconds=Math.ceil((providerRetryAt-Date.now())/1000);throw error;}
  const slot=Math.max(Date.now(),nextProviderAt);nextProviderAt=slot+1200;await new Promise(resolve=>setTimeout(resolve,Math.max(0,slot-Date.now())));
  if(Date.now()<providerRetryAt){const error=new Error('The flight provider is rate-limiting requests. Please wait before refreshing.');error.retrySeconds=Math.ceil((providerRetryAt-Date.now())/1000);throw error;}
  const a=AIRPORTS[airport];const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),18000);
  let body;try{const response=await upstream(`https://api.adsb.lol/v2/point/${a.lat}/${a.lon}/${radius}`,{headers:{Accept:'application/json','User-Agent':'FlowBetter-airport-map/1.0'},signal:controller.signal});
   if(!response.ok){const wait=Math.min(3600,Math.max(30,Number(response.headers.get('retry-after'))||60));const error=new Error(response.status===429?'The flight provider is rate-limiting requests. Please wait before refreshing.':'The live flight provider is temporarily unavailable.');error.retrySeconds=wait;if(response.status===429)providerRetryAt=Date.now()+wait*1000;throw error;}
   body=normalizeFlights(await readBounded(response),airport,radius);
  }finally{clearTimeout(timer);}
  cache.set(key,{body,status:200,headers:{},expires:Date.now()+15000});
  if(cfCache){const write=cfCache.put(cacheKey,json(body,200,{'cache-control':'public, max-age=15'}));if(ctx.waitUntil)ctx.waitUntil(write);else await write;}
  return[body,200,{}];
 }catch(error){const retrySeconds=error.retrySeconds||30;const body={error:error.name==='AbortError'?'The flight provider timed out. Please try again shortly.':error.message?.startsWith('The flight provider')||error.message?.startsWith('The live flight')?error.message:'The live flight feed could not be read. Please try again shortly.',retrySeconds};const headers={'retry-after':String(retrySeconds)};cache.set(key,{body,status:503,headers,expires:Date.now()+retrySeconds*1000});return[body,503,headers];}
 })();pending.set(key,job);try{return json(...await job);}finally{pending.delete(key);}
}

const ASSETS={"/assets/airport-hero.webp":{"type":"image/webp","data":""},"/content.js":{"type":"text/javascript; charset=utf-8","data":""},"/flight-data.js":{"type":"text/javascript; charset=utf-8","data":""},"/flight-map.css":{"type":"text/css; charset=utf-8","data":""},"/flight-map.js":{"type":"text/javascript; charset=utf-8","data":""},"/index.html":{"type":"text/html; charset=utf-8","data":""},"/site.css":{"type":"text/css; charset=utf-8","data":""},"/site.js":{"type":"text/javascript; charset=utf-8","data":""},"/style-tile.html":{"type":"text/html; charset=utf-8","data":""},"/vendor/leaflet/LICENSE":{"type":"text/plain; charset=utf-8","data":""},"/vendor/leaflet/leaflet.css":{"type":"text/css; charset=utf-8","data":""},"/vendor/leaflet/leaflet.js":{"type":"text/javascript; charset=utf-8","data":""}};
export default {async fetch(request,env,ctx){const url=new URL(request.url);if(!['GET','HEAD'].includes(request.method))return new Response('Method not allowed',{status:405,headers:{Allow:'GET, HEAD'}});if(url.pathname==='/api/flight-map')return flightAPI(request,env,ctx);const p=url.pathname==='/'?'/index.html':url.pathname;const asset=ASSETS[p];if(!asset)return new Response('Not found',{status:404});const bytes=Uint8Array.from(atob(asset.data),c=>c.charCodeAt(0));return new Response(request.method==='HEAD'?null:bytes,{headers:{'content-type':asset.type,'cache-control':p.endsWith('.html')?'no-cache':'public, max-age=300','x-content-type-options':'nosniff','referrer-policy':'strict-origin-when-cross-origin'}});}};
